#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#define VW 16
#define NV 2
#define MR 12
#elif defined(__AVX__)
#define VW 8
#define NV 2
#define MR 6
#else
#define VW 4
#define NV 4
#define MR 6
#endif

#define NR (VW * NV)
#define KC 256
#define MC (MR * 8)
#define NC (NR * 8)

typedef float vf __attribute__((vector_size(VW * sizeof(float))));

static float *Ap_buf = NULL, *Bp_buf = NULL;
static size_t Ap_cap = 0, Bp_cap = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

static inline vf vload(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void vstore(float *p, vf v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int first, int mr, int nr)
{
    a = (const float *)__builtin_assume_aligned(a, 16);
    b = (const float *)__builtin_assume_aligned(b, 64);
    vf acc[MR][NV];
#pragma GCC unroll 16
    for (int r = 0; r < MR; r++)
#pragma GCC unroll 4
        for (int v = 0; v < NV; v++)
            acc[r][v] = (vf){0};

    for (int p = 0; p < kc; p++) {
        vf bv[NV];
#pragma GCC unroll 4
        for (int v = 0; v < NV; v++)
            bv[v] = *(const vf *)(b + v * VW);
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            vf av = (vf){0} + a[r];
#pragma GCC unroll 4
            for (int v = 0; v < NV; v++)
                acc[r][v] += av * bv[v];
        }
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (first) {
#pragma GCC unroll 16
            for (int r = 0; r < MR; r++)
#pragma GCC unroll 4
                for (int v = 0; v < NV; v++)
                    vstore(c + r * ldc + v * VW, acc[r][v]);
        } else {
#pragma GCC unroll 16
            for (int r = 0; r < MR; r++)
#pragma GCC unroll 4
                for (int v = 0; v < NV; v++)
                    vstore(c + r * ldc + v * VW,
                           vload(c + r * ldc + v * VW) + acc[r][v]);
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        for (int r = 0; r < MR; r++)
            for (int v = 0; v < NV; v++)
                vstore(tmp + r * NR + v * VW, acc[r][v]);
        for (int r = 0; r < mr; r++) {
            float *cr = c + r * ldc;
            const float *tr = tmp + r * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int ms = (n + MR - 1) / MR;
    int ns = (n + NR - 1) / NR;
    float *Ap = Ap_buf = grow(Ap_buf, &Ap_cap, (size_t)ms * MR * n);
    float *Bp = Bp_buf = grow(Bp_buf, &Bp_cap, (size_t)ns * NR * n);

    int nib = (n + MC - 1) / MC;
    int njb = (n + NC - 1) / NC;

#pragma omp parallel
    {
        /* Pack A: strip s holds rows s*MR..s*MR+MR-1, layout [k][r] */
#pragma omp for schedule(static) nowait
        for (int s = 0; s < ms; s++) {
            float *dst = Ap + (size_t)s * MR * n;
            for (int r = 0; r < MR; r++) {
                int i = s * MR + r;
                if (i < n) {
                    const float *src = A + (size_t)i * n;
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = src[k];
                } else {
                    for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = 0.0f;
                }
            }
        }

        /* Pack B: panel q holds cols q*NR..q*NR+NR-1, layout [k][c] */
#pragma omp for schedule(static)
        for (int q = 0; q < ns; q++) {
            float *dst = Bp + (size_t)q * NR * n;
            int j0 = q * NR;
            int w = n - j0 < NR ? n - j0 : NR;
            for (int k = 0; k < n; k++) {
                const float *src = B + (size_t)k * n + j0;
                float *d = dst + (size_t)k * NR;
                int j = 0;
                for (; j < w; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }

#pragma omp for collapse(2) schedule(dynamic, 1)
        for (int ib = 0; ib < nib; ib++)
            for (int jb = 0; jb < njb; jb++) {
                int i0 = ib * MC, i1 = i0 + MC < n ? i0 + MC : n;
                int j0 = jb * NC, j1 = j0 + NC < n ? j0 + NC : n;
                for (int k0 = 0; k0 < n; k0 += KC) {
                    int kc = n - k0 < KC ? n - k0 : KC;
                    int first = (k0 == 0);
                    for (int jr = j0; jr < j1; jr += NR) {
                        const float *bp = Bp + (size_t)(jr / NR) * NR * n + (size_t)k0 * NR;
                        int nr = j1 - jr < NR ? j1 - jr : NR;
                        for (int ir = i0; ir < i1; ir += MR) {
                            const float *ap = Ap + (size_t)(ir / MR) * MR * n + (size_t)k0 * MR;
                            int mr = i1 - ir < MR ? i1 - ir : MR;
                            kernel(kc, ap, bp, C + (size_t)ir * n + jr, n, first, mr, nr);
                        }
                    }
                }
            }
    }
}
